<?php require dirname(__DIR__).'/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$errors=$service->contact($_POST);if(!$errors){flash('success','Thanks — your message was saved successfully.');redirect('/contact.php');}}$title='Contact | Abhishek Raj';require ROOT.'/app/Views/layouts/header.php'; ?><section class="container narrow py-5"><p class="eyebrow text-primary">GET IN TOUCH</p><h1>Let’s talk about your next idea.</h1><p class="lead">Use this form to send a message. It is validated and inserted into the configured database.</p><?php if($m=flash('success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;if(!empty($errors)):?><div class="alert alert-danger"><?php foreach($errors as $e):?><div><?=e($e)?></div><?php endforeach;?></div><?php endif;?><form method="post" class="contact-form needs-validation" novalidate><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input required minlength="2" maxlength="100" name="name" class="form-control" value="<?=e($_POST['name']??'')?>"></div><div class="col-md-6"><label class="form-label">Email</label><input required type="email" name="email" class="form-control" value="<?=e($_POST['email']??'')?>"></div><div class="col-12"><label class="form-label">Subject</label><input required maxlength="150" name="subject" class="form-control" value="<?=e($_POST['subject']??'')?>"></div><div class="col-12"><label class="form-label">Message</label><textarea required minlength="10" maxlength="3000" name="message" rows="6" class="form-control"><?=e($_POST['message']??'')?></textarea></div><div class="col-12"><button class="btn btn-primary btn-lg">Send message <i class="bi bi-send"></i></button></div></div></form></section><?php require ROOT.'/app/Views/layouts/footer.php'; ?>
